/**
 * Design token generator and drift verifier.
 *
 * Reads `design/figma-tokens.json` and `design/tokens.config.ts`, then generates:
 * 1. `src/styles/tokens.css` (Tailwind v4 `@theme` and mode-scoped CSS variables)
 * 2. `src/lib/design-tokens.ts` (Typed token metadata for runtime/test inspection)
 *
 * Usage:
 * - `npm run tokens`       -> writes generated files to disk
 * - `npm run tokens:check` -> verifies disk files match generated output (exits 1 on drift)
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'

import figmaTokens from '../design/figma-tokens.json'
import { tokensConfig } from '../design/tokens.config'

const ROOT_DIR = resolve(import.meta.dirname, '..')
const CSS_OUT_PATH = resolve(ROOT_DIR, 'src/styles/tokens.css')
const TS_OUT_PATH = resolve(ROOT_DIR, 'src/lib/design-tokens.ts')

/**
 * Converts a pixel measurement to a rem string with up to 4 decimal places.
 *
 * @param px - Value in pixels (assuming 16px root font size).
 * @returns Formatted rem string (e.g., `1.5rem`).
 */
export function rem(px: number): string {
  return `${+(px / 16).toFixed(4)}rem`
}

/**
 * Generates a CSS `clamp()` expression that interpolates linearly between
 * `minPx` at `minVw` and `maxPx` at `maxVw` using rem + vw units.
 *
 * @param minPx - Minimum size in pixels.
 * @param maxPx - Maximum size in pixels.
 * @param minVw - Lower viewport boundary in pixels.
 * @param maxVw - Upper viewport boundary in pixels.
 * @returns CSS `clamp(minRem, interceptRem + slopeVw, maxRem)` string.
 */
export function fluid(minPx: number, maxPx: number, minVw: number, maxVw: number): string {
  if (minPx === maxPx) return rem(maxPx)
  const slope = (maxPx - minPx) / (maxVw - minVw)
  const intercept = minPx - slope * minVw
  const sign = intercept >= 0 ? '+' : '-'
  const absInterceptRem = rem(Math.abs(intercept))
  const slopeVw = `${+(slope * 100).toFixed(4)}vw`
  return `clamp(${rem(minPx)}, ${absInterceptRem} ${sign} ${slopeVw}, ${rem(maxPx)})`
}

/**
 * Builds the contents of `src/styles/tokens.css`.
 *
 * @returns Generated CSS string.
 */
export function generateTokensCss(): string {
  const { grid, colors, typography, radius, shadows, meta } = figmaTokens
  const { typographyMobile, layout, motion } = tokensConfig

  const mobileVw = grid.mobile.width
  const tabletVw = grid.tablet.width
  const desktopVw = grid.desktop.width

  const lines: string[] = [
    '/* GENERATED by scripts/tokens.ts — DO NOT EDIT MANUALLY. Run `npm run tokens`. */',
    '',
    '@theme {',
    '  /* Reset default Tailwind palette so components only use project tokens */',
    '  --color-*: initial;',
    '  --color-transparent: transparent;',
    '  --color-current: currentColor;',
    '',
    '  /* Primitive colors */',
  ]

  for (const [name, hex] of Object.entries(colors.primitive)) {
    lines.push(`  --color-${name}: ${hex};`)
  }

  lines.push('', '  /* Semantic alias colors (mapped to mode-aware CSS custom properties) */')
  for (const name of Object.keys(colors.alias.light)) {
    lines.push(`  --color-${name}: var(--alias-${name});`)
  }

  lines.push(
    '',
    '  /* Responsive breakpoints (mobile-first, rem-based for WCAG zoom compliance) */',
    '  --breakpoint-sm: 40rem;',
    '  --breakpoint-md: 48rem;',
    '  --breakpoint-lg: 64rem;',
    '  --breakpoint-xl: 80rem;',
    '  --breakpoint-2xl: 96rem;',
    '',
    '  /* Font families */',
    `  --font-sans: '${meta.fontFamily}', 'Inter Fallback', system-ui, -apple-system, sans-serif;`,
    '',
    '  /* Typography scale */',
  )

  for (const [styleName, spec] of Object.entries(typography)) {
    const mobileCfg = typographyMobile[styleName]
    const sizeValue =
      mobileCfg && mobileCfg.fluid
        ? fluid(mobileCfg.mobileSizePx, spec.desktopSizePx, mobileVw, desktopVw)
        : rem(spec.desktopSizePx)

    lines.push(`  --text-${styleName}: ${sizeValue};`)
    lines.push(`  --text-${styleName}--line-height: ${spec.lineHeightRatio};`)
    if (spec.letterSpacingEm !== 0) {
      lines.push(`  --text-${styleName}--letter-spacing: ${spec.letterSpacingEm}em;`)
    }
    lines.push(`  --text-${styleName}--font-weight: ${spec.fontWeight};`)
  }

  lines.push(
    '',
    '  /* Layout spacing & container tokens */',
    '  --spacing-page: var(--page-margin);',
    '  --spacing-gutter: var(--grid-gutter);',
    '  --spacing-section-top: var(--section-top);',
    '  --spacing-section-bottom: var(--section-bottom);',
    '  --spacing-section-gap: var(--section-gap);',
    '  --spacing-header: var(--header-height);',
    `  --container-site: ${rem(grid.desktop.width)};`,
    `  --container-content: ${rem(grid.desktop.contentWidth)};`,
    '',
    '  /* Border radius tokens */',
  )

  for (const [key, pxVal] of Object.entries(radius)) {
    const value = pxVal >= 9999 ? '9999px' : rem(pxVal)
    lines.push(`  --radius-${key}: ${value};`)
  }
  lines.push('  --radius-sm: var(--radius-6);')
  lines.push('  --radius-md: var(--radius-8);')
  lines.push('  --radius-lg: var(--radius-12);')
  lines.push('  --radius-xl: var(--radius-16);')

  lines.push('', '  /* Elevation shadows */')
  for (const [key, val] of Object.entries(shadows)) {
    lines.push(`  --shadow-${key}: ${val};`)
  }

  lines.push(
    '',
    '  /* Motion tokens */',
    `  --ease-standard: ${motion.easeStandard};`,
    `  --ease-out: ${motion.easeOut};`,
    `  --ease-in: ${motion.easeIn};`,
    '}',
    '',
    '/* Piecewise fluid layout variables (Mobile -> Tablet -> Desktop D) */',
    ':root {',
    `  --page-margin: ${fluid(grid.mobile.marginPx, grid.tablet.marginPx, mobileVw, tabletVw)};`,
    `  --grid-gutter: ${fluid(grid.mobile.gutterPx, grid.tablet.gutterPx, mobileVw, tabletVw)};`,
    `  --section-top: ${fluid(layout.sectionPaddingTop.mobilePx, layout.sectionPaddingTop.desktopPx, mobileVw, desktopVw)};`,
    `  --section-bottom: ${fluid(layout.sectionPaddingBottom.mobilePx, layout.sectionPaddingBottom.desktopPx, mobileVw, desktopVw)};`,
    `  --section-gap: ${fluid(layout.sectionGap.mobilePx, layout.sectionGap.desktopPx, mobileVw, desktopVw)};`,
    `  --header-height: ${rem(layout.headerHeightPx)};`,
    `  --duration-fast: ${motion.durationFast};`,
    `  --duration-base: ${motion.durationBase};`,
    `  --duration-slow: ${motion.durationSlow};`,
    '}',
    '',
    '@media (min-width: 48rem) {',
    '  :root {',
    `    --page-margin: ${fluid(grid.tablet.marginPx, grid.desktop.marginPx, tabletVw, desktopVw)};`,
    `    --grid-gutter: ${fluid(grid.tablet.gutterPx, grid.desktop.gutterPx, tabletVw, desktopVw)};`,
    '  }',
    '}',
    '',
    '/* Mode-scoped semantic color aliases */',
    ':root,',
    '.light {',
  )

  for (const [name, hex] of Object.entries(colors.alias.light)) {
    lines.push(`  --alias-${name}: ${hex};`)
  }
  lines.push('}', '', '.dark {')

  for (const [name, hex] of Object.entries(colors.alias.dark)) {
    lines.push(`  --alias-${name}: ${hex};`)
  }
  lines.push('}', '')

  return lines.join('\n')
}

/**
 * Builds the contents of `src/lib/design-tokens.ts`.
 *
 * @returns Generated TypeScript source string.
 */
export function generateTokensTs(): string {
  const { grid, colors, typography, radius, shadows, meta } = figmaTokens
  const { typographyMobile, layout, motion } = tokensConfig

  return `/**
 * GENERATED by scripts/tokens.ts — DO NOT EDIT MANUALLY.
 * Run \`npm run tokens\` to update.
 */

export const DESIGN_META = ${JSON.stringify(meta, null, 2)} as const

export const GRID_TOKENS = ${JSON.stringify(grid, null, 2)} as const

export const COLOR_TOKENS = ${JSON.stringify(colors, null, 2)} as const

export const TYPOGRAPHY_TOKENS = ${JSON.stringify(typography, null, 2)} as const

export const TYPOGRAPHY_MOBILE_CONFIG = ${JSON.stringify(typographyMobile, null, 2)} as const

export const RADIUS_TOKENS = ${JSON.stringify(radius, null, 2)} as const

export const SHADOW_TOKENS = ${JSON.stringify(shadows, null, 2)} as const

export const LAYOUT_RHYTHM_TOKENS = ${JSON.stringify(layout, null, 2)} as const

export const MOTION_TOKENS = ${JSON.stringify(motion, null, 2)} as const
`
}

function main(): void {
  const checkOnly = process.argv.includes('--check')
  const expectedCss = generateTokensCss()
  const expectedTs = generateTokensTs()

  if (checkOnly) {
    const cssExists = existsSync(CSS_OUT_PATH)
    const tsExists = existsSync(TS_OUT_PATH)

    if (!cssExists || !tsExists) {
      console.error(
        '✗ Token artifacts are missing. Run `npm run tokens` to generate src/styles/tokens.css and src/lib/design-tokens.ts.',
      )
      process.exit(1)
    }

    const currentCss = readFileSync(CSS_OUT_PATH, 'utf8')
    const currentTs = readFileSync(TS_OUT_PATH, 'utf8')

    if (currentCss !== expectedCss || currentTs !== expectedTs) {
      console.error(
        '✗ Design token drift detected! Generated files do not match design/figma-tokens.json + design/tokens.config.ts.\n  Run `npm run tokens` to synchronize.',
      )
      process.exit(1)
    }

    console.log('✓ Design tokens are in sync (src/styles/tokens.css & src/lib/design-tokens.ts)')
    return
  }

  mkdirSync(dirname(CSS_OUT_PATH), { recursive: true })
  mkdirSync(dirname(TS_OUT_PATH), { recursive: true })

  writeFileSync(CSS_OUT_PATH, expectedCss, 'utf8')
  writeFileSync(TS_OUT_PATH, expectedTs, 'utf8')

  console.log('✓ Generated src/styles/tokens.css and src/lib/design-tokens.ts')
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main()
}
